def histogram(test):
    # Split the input string into a list of characters
    chars = test.split()

    # Initialize an empty dictionary to store character counts
    char_counts = {}

    # Iterate over each character in the list
    for char in chars:
        # If the character is already in the dictionary, increment its count
        if char in char_counts:
            char_counts[char] += 1
        # Otherwise, add the character to the dictionary with a count of 1
        else:
            char_counts[char] = 1

    # Find the maximum count
    max_count = max(char_counts.values()) if char_counts else 0

    # Return only the characters that have this maximum count
    return {k: v for k, v in char_counts.items() if v == max_count}
