def triples_sum_to_zero(l: list):
    # Sort the list to make it easier to find three distinct elements that sum to zero.
    l.sort()

    # Iterate through each element in the list, treating it as a potential first element of a triple.
    for i in range(len(l) - 2):
        # Skip duplicates to ensure we have three distinct elements.
        if i > 0 and l[i] == l[i - 1]:
            continue

        # Use two pointers to find the other two elements that sum with the current element to zero.
        left, right = i + 1, len(l) - 1
        while left < right:
            triple_sum = l[i] + l[left] + l[right]

            if triple_sum == 0:
                return True
            elif triple_sum < 0:
                left += 1
            else:
                right -= 1

    # If no such triple is found, return False.
    return False
