def tri(n):
    if n == 0:
        return []
    elif n == 1:
        return [3]
    elif n == 2:
        return [3, 2]

    sequence = [3, 2]
    for i in range(3, n + 1):
        if i % 2 == 0:
            next_value = 1 + i // 2
        else:
            next_value = sequence[i - 1] + sequence[i - 2] + sequence[i + 1]

        sequence.append(next_value)

    return sequence
